class Solution:
    def topScoringStudents(self, students, courses, enrollments):
        req = {}
        for cid, name, cr, maj in courses:
            req.setdefault(maj, set()).add(cid)
        got = {}
        for sid, cid, sem, g in enrollments:
            if g == 'A':
                got.setdefault(sid, set()).add(cid)
        res = []
        for sid, name, maj in students:
            if req.get(maj, set()) <= got.get(sid, set()):
                res.append(sid)
        return sorted(res)

