class Solution {
public:
    vector<int> topScoringStudents(vector<vector<string>>& students,
                                   vector<vector<string>>& courses,
                                   vector<vector<string>>& enrollments) {
        unordered_map<string, unordered_set<string>> req;
        for (auto& c : courses) req[c[3]].insert(c[0]);
        unordered_map<string, unordered_set<string>> got;
        for (auto& e : enrollments)
            if (e[3] == "A") got[e[0]].insert(e[1]);
        vector<int> res;
        for (auto& s : students) {
            bool ok = true;
            for (auto& cid : req[s[2]])
                if (!got[s[0]].count(cid)) { ok = false; break; }
            if (ok) res.push_back(stoi(s[0]));
        }
        sort(res.begin(), res.end());
        return res;
    }
};

