class Solution {
    public List<Integer> topScoringStudents(List<List<String>> students,
                                            List<List<String>> courses,
                                            List<List<String>> enrollments) {
        Map<String, Set<String>> req = new HashMap<>();
        for (List<String> c : courses) req.computeIfAbsent(c.get(3), z -> new HashSet<>()).add(c.get(0));
        Map<String, Set<String>> got = new HashMap<>();
        for (List<String> e : enrollments)
            if (e.get(3).equals("A")) got.computeIfAbsent(e.get(0), z -> new HashSet<>()).add(e.get(1));
        List<Integer> res = new ArrayList<>();
        for (List<String> s : students) {
            Set<String> need = req.getOrDefault(s.get(2), Set.of());
            if (got.getOrDefault(s.get(0), Set.of()).containsAll(need))
                res.add(Integer.parseInt(s.get(0)));
        }
        Collections.sort(res);
        return res;
    }
}

