var topScoringStudents = function(students, courses, enrollments) {
    const req = {}, got = {};
    for (const [cid,,, maj] of courses) (req[maj] ||= new Set()).add(cid);
    for (const [sid, cid,, g] of enrollments)
        if (g === 'A') (got[sid] ||= new Set()).add(cid);
    const res = [];
    for (const [sid,, maj] of students) {
        let ok = true;
        for (const cid of (req[maj] || [])) if (!(got[sid] || new Set()).has(cid)) { ok = false; break; }
        if (ok) res.push(+sid);
    }
    return res.sort((a, b) => a - b);
};

